const http = require('http');
const { spawn } = require('child_process');
const url = require('url');

const PORT = 3000;

// Function to execute ClickHouse queries
function executeClickHouseQuery(query) {
    return new Promise((resolve, reject) => {
        const process = spawn('clickhouse-client', ['--query', query, '--format', 'JSONEachRow']);

        let output = '';
        let error = '';

        process.stdout.on('data', (data) => {
            output += data.toString();
        });

        process.stderr.on('data', (data) => {
            error += data.toString();
        });

        process.on('close', (code) => {
            if (code === 0) {
                try {
                    // Parse JSONEachRow format (one JSON object per line)
                    const lines = output.trim().split('\n').filter(line => line.trim());
                    const result = lines.map(line => JSON.parse(line));
                    resolve(result);
                } catch (e) {
                    reject(new Error('Failed to parse JSON: ' + e.message));
                }
            } else {
                reject(new Error('ClickHouse error: ' + error));
            }
        });
    });
}

// API handlers
async function handleTopProducts(req, res) {
    try {
        const query = 'SELECT * FROM analytics.top_products ORDER BY purchase_count DESC LIMIT 10';
        const result = await executeClickHouseQuery(query);

        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify(result, null, 2));
    } catch (error) {
        console.error('Error in /api/top-products:', error);
        res.writeHead(500, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: error.message }));
    }
}

async function handleFunnel(req, res) {
    try {
        const query = 'SELECT * FROM analytics.conversion_funnel ORDER BY step';
        const result = await executeClickHouseQuery(query);

        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify(result, null, 2));
    } catch (error) {
        console.error('Error in /api/funnel:', error);
        res.writeHead(500, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: error.message }));
    }
}

async function handleHourly(req, res) {
    try {
        const query = 'SELECT * FROM analytics.hourly_activity ORDER BY hour';
        const result = await executeClickHouseQuery(query);

        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify(result, null, 2));
    } catch (error) {
        console.error('Error in /api/hourly:', error);
        res.writeHead(500, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: error.message }));
    }
}

// Main server
const server = http.createServer(async (req, res) => {
    const parsedUrl = url.parse(req.url, true);
    const pathname = parsedUrl.pathname;

    // Add CORS headers
    res.setHeader('Access-Control-Allow-Origin', '*');
    res.setHeader('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE');
    res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

    console.log(`${new Date().toISOString()} ${req.method} ${pathname}`);

    if (req.method === 'GET') {
        if (pathname === '/api/top-products') {
            await handleTopProducts(req, res);
        } else if (pathname === '/api/funnel') {
            await handleFunnel(req, res);
        } else if (pathname === '/api/hourly') {
            await handleHourly(req, res);
        } else if (pathname === '/') {
            // Health check endpoint
            res.writeHead(200, { 'Content-Type': 'application/json' });
            res.end(JSON.stringify({
                status: 'ok',
                endpoints: ['/api/top-products', '/api/funnel', '/api/hourly']
            }));
        } else {
            res.writeHead(404, { 'Content-Type': 'application/json' });
            res.end(JSON.stringify({ error: 'Not found' }));
        }
    } else {
        res.writeHead(405, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Method not allowed' }));
    }
});

server.listen(PORT, () => {
    console.log(`Analytics API server running on port ${PORT}`);
    console.log('Available endpoints:');
    console.log('  GET /api/top-products - Top products by purchase count');
    console.log('  GET /api/funnel - Conversion funnel stats');
    console.log('  GET /api/hourly - Hourly activity breakdown');
});

// Graceful shutdown
process.on('SIGINT', () => {
    console.log('\nShutting down server...');
    server.close(() => {
        console.log('Server closed.');
        process.exit(0);
    });
});

